function chunk(list, size) {
  const out = [];
  for (let i = 0; i < list.length; i += size) out.push(list.slice(i, i + size));
  return out;
}

function buildBatches() {
  const batches = [];
  chunk(QUEUE, STD_BATCH).forEach((skus, i) => batches.push({ key: `std:${i}`, phase: 'std', skus }));
  chunk(QUEUE, HI_BATCH).forEach((skus, i) => batches.push({ key: `hi:${i}`, phase: 'hi', skus }));
  return batches;
}

function progressOf(batch, manifestImages) {
  let n = 0;
  for (const sku of batch.skus) {
    const e = manifestImages && manifestImages[sku];
    if (!e) continue;
    if (batch.phase === 'std' && e.count > 0) n++;
    if (batch.phase === 'hi' && e.hiCount > 0) n++;
  }
  return n;
}

function triggerUrlFor(batch, siteUrl) {
  const base = String(siteUrl).replace(/\/$/, '');
  const skus = batch.skus.join(',');
  if (batch.phase === 'std') {
    return `${base}/.netlify/functions/image-sync-background?skus=${encodeURIComponent(skus)}&skip-done=1&no-hi=1`;
  }
  return `${base}/.netlify/functions/image-sync-background?hi-only=1&skus=${encodeURIComponent(skus)}`;
}

exports.handler = async (event) => {
  try {
    if (process.env.GAPFILL_AUTO_PAUSED === '1') {
      console.log('Gapfill scheduler: paused (GAPFILL_AUTO_PAUSED=1) — triggering nothing.');
      return { statusCode: 200, body: JSON.stringify({ paused: true }) };
    }
    let blobs;
    try { blobs = require('@netlify/blobs'); } catch {
      throw new Error('@netlify/blobs is not installed.');
    }
    try { blobs.connectLambda(event); } catch (e) { console.warn('connectLambda skipped:', e.message); }
    const store = blobs.getStore(STORE);
    let state = null;
    try {
      state = await store.get(STATE_KEY, { type: 'json' });
    } catch (e) {
      console.error('Gapfill scheduler: cannot read state, skipping this wake:', e.message);
      return { statusCode: 200, body: JSON.stringify({ skipped: 'state-read-failed' }) };
    }
    if (!state || typeof state !== 'object') state = { done: {}, lastTriggeredAt: null, lastTriggeredJob: null, batches: {} };
    state.done = state.done || {};
    state.batches = state.batches || {};
    let manifestImages = {};
    try {
      const m = await store.get('images.json', { type: 'json' });
      if (m && m.images) manifestImages = m.images;
    } catch (e) {
      console.warn('Gapfill scheduler: manifest read failed, progress treated as 0:', e.message);
    }
    const batches = buildBatches();
    // Advance through finished / stalled batches without triggering.
    let current = null;
    for (const batch of batches) {
      const bstate = state.batches[batch.key] || (state.batches[batch.key] = { triggers: 0, progressAtTrigger: null, noProgressStreak: 0, leftover: [] });
      if (state.done[batch.key]) continue;
      const progress = progressOf(batch, manifestImages);
      if (progress >= batch.skus.length) {
        state.done[batch.key] = { at: new Date().toISOString(), progress };
        continue;
      }
      if (bstate.triggers > 0 && bstate.progressAtTrigger !== null && progress === bstate.progressAtTrigger) {
        bstate.noProgressStreak = (bstate.noProgressStreak || 0) + 1;
        if (bstate.noProgressStreak >= 2 || bstate.triggers >= MAX_TRIGGERS_PER_BATCH) {
          bstate.leftover = batch.skus.filter((sku) => {
            const e = manifestImages[sku];
            return batch.phase === 'std' ? !(e && e.count > 0) : !(e && e.hiCount > 0);
          });
          state.done[batch.key] = { at: new Date().toISOString(), progress, leftover: bstate.leftover };
          console.log(`Gapfill scheduler: batch ${batch.key} marked done after no progress (progress ${progress}/${batch.skus.length}, leftover ${bstate.leftover.length}).`);
          continue;
        }
      } else if (bstate.triggers > 0 && progress > (bstate.progressAtTrigger || 0)) {
        bstate.noProgressStreak = 0;
      }
      if (bstate.triggers >= MAX_TRIGGERS_PER_BATCH) {
        bstate.leftover = batch.skus.filter((sku) => {
          const e = manifestImages[sku];
          return batch.phase === 'std' ? !(e && e.count > 0) : !(e && e.hiCount > 0);
        });
        state.done[batch.key] = { at: new Date().toISOString(), progress, leftover: bstate.leftover };
        continue;
      }
      current = batch;
      break;
    }
    if (!current) {
      console.log('Gapfill scheduler: all jobs done — gap-fill complete, triggering nothing.');
      return { statusCode: 200, body: JSON.stringify({ complete: true }) };
    }
    if (state.lastTriggeredAt) {
      const gap = Date.now() - Date.parse(state.lastTriggeredAt);
      if (!Number.isNaN(gap) && gap < MIN_TRIGGER_GAP_MS) {
        console.log(`Gapfill scheduler: last trigger ${Math.round(gap / 1000)}s ago (< 20 min) — previous job may still run, skipping this wake. Next job: ${current.key}.`);
        return { statusCode: 200, body: JSON.stringify({ waiting: true, nextJob: current.key }) };
      }
    }
    const siteUrl = process.env.URL || 'https://xl-arms.netlify.app';
    const url = triggerUrlFor(current, siteUrl);
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 15000);
    let res;
    try {
      res = await fetch(url, { signal: controller.signal });
    } catch (e) {
      clearTimeout(timer);
      console.error(`Gapfill scheduler: trigger fetch failed for ${current.key}:`, e.message);
      return { statusCode: 200, body: JSON.stringify({ triggerFailed: current.key }) };
    }
    clearTimeout(timer);
    if (res.status !== 202) {
      console.error(`Gapfill scheduler: trigger for ${current.key} returned ${res.status} (expected 202) — not recording trigger, next wake retries.`);
      return { statusCode: 200, body: JSON.stringify({ triggerFailed: current.key, status: res.status }) };
    }
    const bstate = state.batches[current.key];
    bstate.triggers = (bstate.triggers || 0) + 1;
    bstate.progressAtTrigger = progressOf(current, manifestImages);
    state.lastTriggeredAt = new Date().toISOString();
    state.lastTriggeredJob = current.key;
    try {
      await store.set(STATE_KEY, JSON.stringify(state));
    } catch (e) {
      console.warn('Gapfill scheduler: trigger recorded in memory only, state save failed:', e.message);
    }
    console.log(`Gapfill scheduler: triggered ${current.key} (${current.phase}, ${current.skus.length} SKUs, trigger ${bstate.triggers}) — ${url.slice(0, 120)}...`);
    return { statusCode: 200, body: JSON.stringify({ triggered: current.key }) };
  } catch (e) {
    console.error('Gapfill scheduler FAILED:', e.message);
    return { statusCode: 200, body: JSON.stringify({ error: e.message }) };
  }
};

module.exports.buildBatches = buildBatches;
module.exports.progressOf = progressOf;
module.exports.triggerUrlFor = triggerUrlFor;
